Object.assign(SNIP,{"l35vt": "// p->ten() với ten là hàm ảo, máy làm 3 việc:\n// 1. đọc vptr nằm ở đầu đối tượng *p        → địa chỉ vtable của lớp thật (Tron)\n// 2. lấy ô số k trong vtable (ten là ô [0]) → địa chỉ hàm Tron::ten\n// 3. gọi hàm ở địa chỉ đó, truyền this = p", "l35syn": "class Hinh {\npublic:\n    virtual string ten() const {            // hàm ảo: lớp con được phép thay\n        return \"hinh chung\";\n    }\n    virtual ~Hinh() {}                      // lớp có hàm ảo thì hàm hủy cũng nên ảo\n};\n\nclass Tron : public Hinh {\npublic:\n    string ten() const override {           // override: \"tôi đang thay hàm ảo của lớp cha\"\n        return \"hinh tron\";\n    }\n};\n\nTron t;\nHinh* p = &t;\ncout << p->ten();      // \"hinh tron\": chọn theo đối tượng thật, không theo kiểu con trỏ"});PRESET_NOTES["l35"]={"Ví dụ: virtual đổi hàm được gọi": "ten là hàm ảo nên p->ten() và r.ten() đi theo đối tượng thật (Tron). loai là hàm thường nên p->loai() vẫn theo kiểu con trỏ (Hinh). Gọi trực tiếp trên t thì cả hai đều là bản của Tron.", "Ví dụ: vptr làm đối tượng lớn thêm 8 byte": "Thuong chỉ có một int: 4 byte. CoAo có thêm vptr 8 byte ở đầu, x đứng sau, làm tròn lên bội của 8: 16 byte. Con thêm y vào chỗ trống sau x nên vẫn 16. Trong Hình động, b và c có vptr trỏ tới hai vtable khác nhau; ô [0] của vtable Con ghi Con::lay.", "Ví dụ: Một vòng lặp, nhiều loại hình": "ds chỉ biết mỗi phần tử là Hinh*. Vòng for gọi h->dienTich() giống hệt nhau cho mọi phần tử, nhưng mỗi lần máy đi theo vptr của đối tượng trên heap tới đúng vtable (Tron hoặc ChuNhat). Hàm hủy ảo giúp delete h dọn đúng loại đối tượng.", "Ví dụ: Hàm hủy ảo": "~Cha là virtual nên delete p đi theo vptr tới ~Con trước (trả mảng duLieu), rồi tới ~Cha. Hãy thử xóa chữ virtual trước ~Cha: g++ cảnh báo, chỉ ~Cha chạy và 3 ô nhớ bị rò rỉ.", "Lỗi: quên hàm hủy ảo": "Cha có hàm ảo nhưng hàm hủy thường. delete p chỉ gọi ~Cha (theo kiểu con trỏ), ~Con không bao giờ chạy. g++ cảnh báo: deleting object of polymorphic class type 'Cha' which has non-virtual destructor might cause undefined behavior. Sửa: virtual ~Cha().", "Ví dụ: Gọi hàm ảo trong hàm tạo": "Lúc Hinh() chạy, phần Tron chưa có (r chưa được gán), nên vptr đang trỏ vtable Hinh và chao() gọi Hinh::chao. Xong phần Hinh, vptr mới chuyển sang vtable Tron. Bấm Từng bước để thấy ô vptr đổi bảng.", "Ví dụ: Cắt lát đối tượng": "theoGiaTri nhận một DongVat mới, chép từ phần DongVat của m: phần Meo bị cắt mất, vptr của bản sao trỏ vtable DongVat nên keu() trả \"...\". theoThamChieu gắn thẳng với m nên vẫn gọi Meo::keu.", "Lỗi: override sai chữ ký": "Hinh::ve có const, Tron::ve thì không: hai hàm khác chữ ký nên Tron::ve không ghi đè được gì. Nhờ override, g++ báo lỗi ngay: marked 'override', but does not override. Nếu không có override, chương trình vẫn dịch được và lặng lẽ in \"Ve hinh\"."};EX_HINTS["l35"]=[["Mỗi lớp con chỉ cần một hàm: string keu() const override { return \"...\"; }.", "Vòng in chỉ cần d->keu(): hàm ảo tự chọn đúng lớp."], ["Mỗi lớp con có hàm tạo gọi NhanVien(t) và một hàm long long luong() const override.", "Chỉ đổi người cao nhất khi lương lớn hơn hẳn (>), để bằng nhau thì giữ người nhập trước."], ["TamGiac cần sqrt trong <cmath> (đã include sẵn).", "Giữ một con trỏ Hinh* lon tới hình lớn nhất; chỉ đổi khi diện tích lớn hơn hẳn."]];
/* ===================== BÀI 35 · Hàm ảo và vtable ===================== */
/* Bài 35 · Hàm ảo và vtable
   Sinh bởi công cụ soạn bài: ví dụ cho trình mô phỏng (kèm hình động), bài tập chấm tự động.
   Trắc nghiệm ở quiz.json, gợi ý ở hints.json, lời giải ở solutions/ (nội dung bảo vệ). */
const P35=[{label:"Ví dụ: virtual đổi hàm được gọi",input:"",code:"#include <iostream>\n#include <string>\nusing namespace std;\n\nclass Hinh {\npublic:\n    virtual string ten() const {\n        return \"hinh chung\";\n    }\n    string loai() const {\n        return \"Hinh\";\n    }\n    virtual ~Hinh() {}\n};\n\nclass Tron : public Hinh {\npublic:\n    string ten() const override {\n        return \"hinh tron\";\n    }\n    string loai() const {\n        return \"Tron\";\n    }\n};\n\nint main() {\n    Tron t;\n    Hinh* p = &t;\n    Hinh& r = t;\n    cout << p->ten() << \" | \" << p->loai() << \"\\n\";\n    cout << r.ten() << \" | \" << r.loai() << \"\\n\";\n    cout << t.ten() << \" | \" << t.loai() << \"\\n\";\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Ví dụ: vptr làm đối tượng lớn thêm 8 byte",input:"",code:"#include <iostream>\n#include <string>\nusing namespace std;\n\nclass Thuong {\n    int x = 1;\npublic:\n    int lay() const {\n        return x;\n    }\n};\n\nclass CoAo {\n    int x = 1;\npublic:\n    virtual int lay() const {\n        return x;\n    }\n    virtual ~CoAo() {}\n};\n\nclass Con : public CoAo {\n    int y = 2;\npublic:\n    int lay() const override {\n        return y;\n    }\n};\n\nint main() {\n    Thuong a;\n    CoAo b;\n    Con c;\n    cout << sizeof(a) << \" \" << sizeof(b) << \" \" << sizeof(c) << \"\\n\";\n    CoAo* p = &b;\n    cout << p->lay() << \"\\n\";\n    p = &c;\n    cout << p->lay() << \"\\n\";\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Ví dụ: Một vòng lặp, nhiều loại hình",input:"",code:"#include <iostream>\n#include <iomanip>\n#include <cmath>\n#include <string>\n#include <vector>\nusing namespace std;\n\nclass Hinh {\npublic:\n    virtual double dienTich() const {\n        return 0;\n    }\n    virtual string ten() const {\n        return \"?\";\n    }\n    virtual ~Hinh() {}\n};\n\nclass Tron : public Hinh {\n    double r;\npublic:\n    Tron(double bk) : r(bk) {}\n    double dienTich() const override {\n        return 3.14159 * r * r;\n    }\n    string ten() const override {\n        return \"Tron\";\n    }\n};\n\nclass ChuNhat : public Hinh {\n    double a, b;\npublic:\n    ChuNhat(double x, double y) : a(x), b(y) {}\n    double dienTich() const override {\n        return a * b;\n    }\n    string ten() const override {\n        return \"ChuNhat\";\n    }\n};\n\nint main() {\n    vector<Hinh*> ds;\n    ds.push_back(new Tron(1));\n    ds.push_back(new ChuNhat(2, 3));\n    ds.push_back(new Tron(2));\n    double tong = 0;\n    cout << fixed << setprecision(2);\n    for (Hinh* h : ds) {\n        cout << h->ten() << \" \" << h->dienTich() << \"\\n\";\n        tong += h->dienTich();\n    }\n    cout << \"Tong: \" << tong << \"\\n\";\n    for (Hinh* h : ds) {\n        delete h;\n    }\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Ví dụ: Hàm hủy ảo",input:"",code:"#include <iostream>\n#include <string>\nusing namespace std;\n\nclass Cha {\npublic:\n    virtual void chao() const {\n        cout << \"Cha chao\\n\";\n    }\n    virtual ~Cha() {\n        cout << \"~Cha\\n\";\n    }\n};\n\nclass Con : public Cha {\n    int* duLieu;\npublic:\n    Con() : duLieu(new int[3]) {\n        cout << \"Con xin 3 o nho\\n\";\n    }\n    void chao() const override {\n        cout << \"Con chao\\n\";\n    }\n    ~Con() {\n        delete[] duLieu;\n        cout << \"~Con tra 3 o nho\\n\";\n    }\n};\n\nint main() {\n    Cha* p = new Con();\n    p->chao();\n    delete p;\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Lỗi: quên hàm hủy ảo",input:"",code:"#include <iostream>\n#include <string>\nusing namespace std;\n\nclass Cha {\npublic:\n    virtual void chao() const {\n        cout << \"Cha chao\\n\";\n    }\n    ~Cha() {\n        cout << \"~Cha\\n\";\n    }\n};\n\nclass Con : public Cha {\npublic:\n    void chao() const override {\n        cout << \"Con chao\\n\";\n    }\n    ~Con() {\n        cout << \"~Con\\n\";\n    }\n};\n\nint main() {\n    Cha* p = new Con();\n    p->chao();\n    delete p;\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Ví dụ: Gọi hàm ảo trong hàm tạo",input:"",code:"#include <iostream>\n#include <string>\nusing namespace std;\n\nclass Hinh {\npublic:\n    Hinh() {\n        cout << \"Hinh(): \";\n        chao();\n    }\n    virtual void chao() const {\n        cout << \"toi la Hinh\\n\";\n    }\n    virtual ~Hinh() {}\n};\n\nclass Tron : public Hinh {\n    int r;\npublic:\n    Tron(int bk) : r(bk) {\n        cout << \"Tron(): \";\n        chao();\n    }\n    void chao() const override {\n        cout << \"toi la Tron, r = \" << r << \"\\n\";\n    }\n};\n\nint main() {\n    Tron t(5);\n    Hinh* p = &t;\n    cout << \"main: \";\n    p->chao();\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Ví dụ: Cắt lát đối tượng",input:"",code:"#include <iostream>\n#include <string>\nusing namespace std;\n\nclass DongVat {\npublic:\n    virtual string keu() const {\n        return \"...\";\n    }\n    virtual ~DongVat() {}\n};\n\nclass Meo : public DongVat {\npublic:\n    string keu() const override {\n        return \"Meo meo\";\n    }\n};\n\nvoid theoGiaTri(DongVat d) {\n    cout << \"theo gia tri: \" << d.keu() << \"\\n\";\n}\n\nvoid theoThamChieu(const DongVat& d) {\n    cout << \"theo tham chieu: \" << d.keu() << \"\\n\";\n}\n\nint main() {\n    Meo m;\n    theoGiaTri(m);\n    theoThamChieu(m);\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Lỗi: override sai chữ ký",input:"",code:"#include <iostream>\n#include <string>\nusing namespace std;\n\nclass Hinh {\npublic:\n    virtual void ve() const {\n        cout << \"Ve hinh\\n\";\n    }\n    virtual ~Hinh() {}\n};\n\nclass Tron : public Hinh {\npublic:\n    void ve() override {\n        cout << \"Ve tron\\n\";\n    }\n};\n\nint main() {\n    Tron t;\n    Hinh& h = t;\n    h.ve();\n    return 0;\n}"}];
const sim35=makeSim2(document.getElementById("sim-l35"),{id:"s35",presets:P35});
makeEx2(document.getElementById("ex-l35"),sim35,[{t:"Tiếng kêu của động vật",d:"Viết lớp <code>DongVat<\/code> có hàm ảo <code>string keu() const<\/code> (trả \"...\") và hàm hủy ảo. Ba lớp con <code>Cho<\/code>, <code>Meo<\/code>, <code>Bo<\/code> ghi đè <code>keu()<\/code> trả về lần lượt <code>Gau gau<\/code>, <code>Meo meo<\/code>, <code>Umm bo<\/code>. Nhập n (1 ≤ n ≤ 100) rồi n từ, mỗi từ là <code>cho<\/code>, <code>meo<\/code> hoặc <code>bo<\/code> (từ khác thì tạo DongVat). Lưu tất cả vào <code>vector&lt;DongVat*&gt;<\/code>, sau đó in tiếng kêu của từng con, mỗi con một dòng, rồi giải phóng bộ nhớ.",tests:[{in:"4\ncho meo bo cho",out:"Gau gau\nMeo meo\nUmm bo\nGau gau"},{in:"1\nga",out:"..."},{in:"3\nmeo meo bo",out:"Meo meo\nMeo meo\nUmm bo"}],start:"#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nclass DongVat {\npublic:\n    virtual string keu() const {\n        return \"...\";\n    }\n    virtual ~DongVat() {}\n};\n\n// viết Cho, Meo, Bo kế thừa public DongVat và ghi đè keu()\n\nint main() {\n    int n;\n    cin >> n;\n    vector<DongVat*> ds;\n    for (int i = 0; i < n; i++) {\n        string s;\n        cin >> s;\n        // tạo đúng loại bằng new rồi push_back vào ds\n    }\n    // in tiếng kêu từng con, rồi delete\n    return 0;\n}",need:/virtual\s+string\s+keu[\s\S]*class\s+Cho\s*:\s*public\s+DongVat[\s\S]*vector\s*<\s*DongVat\s*\*\s*>/,needMsg:"Hãy giữ hàm ảo keu của DongVat, viết class Cho : public DongVat (và Meo, Bo), lưu vào vector<DongVat*>."},{t:"Bảng lương đa hình",d:"Lớp <code>NhanVien<\/code> có <code>string ten<\/code>, hàm ảo <code>long long luong() const<\/code> và hàm hủy ảo. Ba loại nhân viên: <code>CD ten muc<\/code> (cố định: lương = muc), <code>GIO ten soGio donGia<\/code> (theo giờ: soGio × donGia), <code>BH ten coBan doanhSo<\/code> (bán hàng: coBan + doanhSo × 5 / 100, chia nguyên). Nhập n rồi n dòng, lưu vào <code>vector&lt;NhanVien*&gt;<\/code>. In từng người <code>ten luong<\/code> theo thứ tự nhập, rồi dòng <code>Tong: ...<\/code> và dòng <code>Cao nhat: ten<\/code> (bằng nhau thì lấy người nhập trước).",tests:[{in:"3\nCD An 8000000\nGIO Binh 120 50000\nBH Chi 5000000 80000000",out:"An 8000000\nBinh 6000000\nChi 9000000\nTong: 23000000\nCao nhat: Chi"},{in:"1\nGIO Tu 0 100000",out:"Tu 0\nTong: 0\nCao nhat: Tu"},{in:"2\nCD A 7000000\nBH B 7000000 19",out:"A 7000000\nB 7000000\nTong: 14000000\nCao nhat: A"}],start:"#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nclass NhanVien {\nprotected:\n    string ten;\npublic:\n    NhanVien(string t) : ten(t) {}\n    string layTen() const { return ten; }\n    virtual long long luong() const { return 0; }\n    virtual ~NhanVien() {}\n};\n\n// viết CoDinh, TheoGio, BanHang kế thừa NhanVien, ghi đè luong()\n\nint main() {\n    int n;\n    cin >> n;\n    vector<NhanVien*> ds;\n    for (int i = 0; i < n; i++) {\n        string loai, ten;\n        cin >> loai >> ten;\n        // đọc thêm số liệu theo loại, tạo đối tượng bằng new\n    }\n    // in từng người, tổng, người cao nhất; giải phóng bộ nhớ\n    return 0;\n}",need:/virtual\s+long\s+long\s+luong[\s\S]*override[\s\S]*vector\s*<\s*NhanVien\s*\*\s*>/,needMsg:"Hãy giữ hàm ảo luong của NhanVien, ghi đè nó ở các lớp con (có override) và lưu vào vector<NhanVien*>."},{t:"Hình có diện tích lớn nhất",d:"Lớp <code>Hinh<\/code> có hàm ảo <code>double dienTich() const<\/code>, <code>string ten() const<\/code> và hàm hủy ảo. Ba lớp con: <code>T r<\/code> (tròn, π = 3.14159), <code>CN a b<\/code> (chữ nhật), <code>TG a b c<\/code> (tam giác, công thức Heron: p = (a+b+c)/2, S = √(p(p−a)(p−b)(p−c)); dữ liệu luôn là tam giác hợp lệ). Tên trả về lần lượt là <code>Tron<\/code>, <code>ChuNhat<\/code>, <code>TamGiac<\/code>. Nhập n rồi n hình. In tổng diện tích, rồi tên và diện tích của hình lớn nhất (bằng nhau thì lấy hình nhập trước), số thực in 2 chữ số thập phân.",tests:[{in:"3\nT 1\nCN 2 3\nTG 3 4 5",out:"15.14\nChuNhat 6.00"},{in:"2\nTG 5 5 6\nT 2",out:"24.57\nTron 12.57"},{in:"1\nCN 0 7",out:"0.00\nChuNhat 0.00"}],start:"#include <iostream>\n#include <iomanip>\n#include <cmath>\n#include <string>\n#include <vector>\nusing namespace std;\n\nclass Hinh {\npublic:\n    virtual double dienTich() const { return 0; }\n    virtual string ten() const { return \"Hinh\"; }\n    virtual ~Hinh() {}\n};\n\n// viết Tron, ChuNhat, TamGiac\n\nint main() {\n    int n;\n    cin >> n;\n    vector<Hinh*> ds;\n    for (int i = 0; i < n; i++) {\n        string k;\n        cin >> k;\n        // T r | CN a b | TG a b c\n    }\n    double tong = 0;\n    // tính tổng, tìm hình lớn nhất\n    cout << fixed << setprecision(2) << tong << \"\\n\";\n    return 0;\n}",need:/virtual\s+double\s+dienTich[\s\S]*class\s+TamGiac\s*:\s*public\s+Hinh[\s\S]*vector\s*<\s*Hinh\s*\*\s*>/,needMsg:"Hãy giữ hàm ảo dienTich của Hinh, viết class TamGiac : public Hinh (và Tron, ChuNhat), lưu vào vector<Hinh*>."}]);

makeQuiz("quiz35","score35",[{"q": "Với <code>Hinh* p = &amp;t;<\/code> (t là Tron) và <code>ve()<\/code> là hàm ảo, <code>p-&gt;ve()<\/code> gọi hàm nào?", "o": ["Hinh::ve, theo kiểu của con trỏ", "Tron::ve, theo đối tượng mà p đang trỏ tới", "Cả hai, lần lượt", "Lỗi biên dịch vì p có kiểu Hinh*"], "a": 1, "e": "Hàm ảo được chọn lúc chạy theo đối tượng thật (liên kết động), qua vptr và vtable."}, {"q": "Trên máy 64 bit, <code>class A { int x; public: virtual void f(); };<\/code> có <code>sizeof(A)<\/code> bằng bao nhiêu?", "o": ["4", "8", "12", "16"], "a": 3, "e": "Thêm vptr 8 byte ở đầu, rồi int x 4 byte, làm tròn lên bội của 8 (căn lề theo vptr): 16."}, {"q": "Trong hàm tạo của lớp cha, gọi một hàm ảo mà lớp con có ghi đè. Bản nào chạy?", "o": ["Bản của lớp con", "Bản của lớp cha", "Không chạy, lỗi biên dịch", "Ngẫu nhiên"], "a": 1, "e": "Khi hàm tạo lớp cha chạy, phần lớp con chưa tồn tại, vptr đang trỏ vtable lớp cha."}, {"q": "Vì sao lớp có hàm ảo nên có hàm hủy ảo?", "o": ["Để đối tượng nhỏ hơn", "Để delete qua con trỏ lớp cha gọi đúng hàm hủy của lớp con", "Vì C++ bắt buộc", "Để hàm tạo chạy nhanh hơn"], "a": 1, "e": "Không có virtual, delete p (Cha* trỏ tới Con) chỉ gọi ~Cha: phần Con không được dọn."}]);

